quality_markers.how_to_detect:
cd "$REPO" && python3 -c "
import re,glob,collections
u=collections.Counter(); per={}
for p in glob.glob('skills/*/*/references/well-architected.md'):
  m=re.search(r'## Official Sources Used\n(.*?)(?=\n## |\Z)',open(p,encoding='utf-8').read(),re.S)
  s=set(re.findall(r'https?://\S+',m.group(1))) if m else set(); per[p]=s; u.update(s)
g={k for k,n in u.items() if n>=100}
print([p for p,s in per.items() if not (s-g)])"
